  dialog.addEventListener('click', e => { if (e.target === dialog) { const r = dialog.getBoundingClientRect(); const m = e as MouseEvent; if (m.clientX < r.left || m.clientX > r.right || m.clientY < r.top || m.clientY > r.bottom) closeDialog(); } });
