        if(hallLineOption)choices.push(`<label>Partner-line hall interpretation<select data-source-choice="hallLine"${locked}><option value="">Leave the hall-line convention unresolved</option><option value="${hallLineOption.convention}">${hallLineOption.convention==='compact-long-lines-hall-v1'?'Review ordered partner line and long-lines progression':hallLineOption.convention==='compact-give-take-hall-v1'?'Review initial partner line and four-count give-and-take':"Start in the source's partner line; review compact travel and finite ends"}</option></select><small>${esc(hallLineDescription(hallLineOption))}</small></label>`);
